import gurobipy as gp
from gurobipy import GRB

def solve_walmart_transportation():
    S = ['S1', 'S2', 'S3', 'S4', 'S5', 'S6', 'S7', 'S8', 'S9', 'S10', 'S11']
    C = ['C1', 'C2', 'C3', 'C4', 'C5', 'C6', 'C7', 'C8', 'C9', 'C10', 'C11', 'C12']
    demand = {'C1': 11, 'C2': 1148, 'C3': 54, 'C4': 833, 'C5': 154, 'C6': 551, 'C7': 7081, 'C8': 76, 'C9': 66, 'C10': 174, 'C11': 15, 'C12': 680}
    supply = {'S1': 4, 'S2': 575, 'S3': 1504, 'S4': 178, 'S5': 228, 'S6': 50, 'S7': 3, 'S8': 6148, 'S9': 6, 'S10': 10673, 'S11': 174}
    cost = {'S1': {'C1': 0.639144477, 'C2': 49.71842803, 'C3': 33.7585774, 'C4': 1570.6731105, 'C5': 1370.4095474, 'C6': 57.35307774, 'C7': 57.18299486, 'C8': 54.92096124, 'C9': 1143.6809092, 'C10': 52.49127008, 'C11': 606.44343996, 'C12': 1192.4686514}, 'S2': {'C1': 605.4786374, 'C2': 64.53562573, 'C3': 478.4779031, 'C4': 887.0480739, 'C5': 65.46111249, 'C6': 71.93605218, 'C7': 41.29015388, 'C8': 70.36038207, 'C9': 35.35892996, 'C10': 1472.7481944, 'C11': 0.600459154, 'C12': 49.86854016}, 'S3': {'C1': 1139.0440075, 'C2': 4.785056325, 'C3': 1805.621423, 'C4': 1302.8958147, 'C5': 2437.3212292, 'C6': 103.8036858, 'C7': 774.6558237, 'C8': 4.515988277, 'C9': 879.7048537, 'C10': 162.7055673, 'C11': 1208.6134848, 'C12': 110.1868852}, 'S4': {'C1': 69.26989891, 'C2': 2105.485387, 'C3': 869.6820232, 'C4': 1494.8985656, 'C5': 310.5376623, 'C6': 98.15455718, 'C7': 103.3691849, 'C8': 1758.878377, 'C9': 97.28540714, 'C10': 94.65040893, 'C11': 1277.2514515, 'C12': 21.63619029}, 'S5': {'C1': 980.411426, 'C2': 899.3108832, 'C3': 1183.032553, 'C4': 402.0986162, 'C5': 81.78864124, 'C6': 1115.681946, 'C7': 123.8042786, 'C8': 1121.146875, 'C9': 0.002445126, 'C10': 1009.645173, 'C11': 35.3480183, 'C12': 1625.434627}, 'S6': {'C1': 1246.7825, 'C2': 2105.796667, 'C3': 1014.339321, 'C4': 1494.668144, 'C5': 362.0173907, 'C6': 98.17142421, 'C7': 2170.405868, 'C8': 97.73187711, 'C9': 97.26834016, 'C10': 1987.990785, 'C11': 70.94396914, 'C12': 389.1598045}, 'S7': {'C1': 57.10860153, 'C2': 23.83616886, 'C3': 78.10572975, 'C4': 742.8068113, 'C5': 1926.079682, 'C6': 454.3789957, 'C7': 458.2901437, 'C8': 465.9307665, 'C9': 28.13860707, 'C10': 524.615426, 'C11': 997.5317838, 'C12': 104.4779449}, 'S8': {'C1': 981.2908605, 'C2': 120.9013, 'C3': 1625.820693, 'C4': 1267.822929, 'C5': 2569.644605, 'C6': 13.47181184, 'C7': 815.1525428, 'C8': 253.4234964, 'C9': 43.76562945, 'C10': 275.9784135, 'C11': 1228.069893, 'C12': 103.4832302}, 'S9': {'C1': 30.53277951, 'C2': 1444.8595, 'C3': 173.5547324, 'C4': 1307.391312, 'C5': 965.2012304, 'C6': 1843.77695, 'C7': 1483.640885, 'C8': 85.32209953, 'C9': 1353.500934, 'C10': 1485.915376, 'C11': 29.42379084, 'C12': 26.61941961}, 'S10': {'C1': 94.11093956, 'C2': 1422.99713, 'C3': 1470.776908, 'C4': 1419.338225, 'C5': 38.94527784, 'C6': 72.20112949, 'C7': 2040.46059, 'C8': 1542.702558, 'C9': 1803.800169, 'C10': 72.94365833, 'C11': 2181.454206, 'C12': 973.5515553}, 'S11': {'C1': 1032.907384, 'C2': 166.3018479, 'C3': 1620.476705, 'C4': 64.66834135, 'C5': 2000.509173, 'C6': 0.002895795, 'C7': 47.0383714, 'C8': 52.99221132, 'C9': 1115.633617, 'C10': 129.7933819, 'C11': 1295.097845, 'C12': 2330.76821}}
    if set(demand.keys()) != set(C):
        raise ValueError('Demand data missing or extra customer groups.')
    if set(supply.keys()) != set(S):
        raise ValueError('Supply data missing or extra stores.')
    if set(cost.keys()) != set(S):
        raise ValueError('Cost data missing or extra stores.')
    for i in S:
        if set(cost[i].keys()) != set(C):
            raise ValueError(f'Cost data for store {i} missing or extra customer groups.')
    m = gp.Model()
    m.Params.MIPGap = 0.0001
    x = m.addVars(S, C, lb=0, vtype=GRB.CONTINUOUS, name='')
    m.setObjective(gp.quicksum((cost[i][j] * x[i, j] for i in S for j in C)), GRB.MINIMIZE)
    for j in C:
        m.addConstr(gp.quicksum((x[i, j] for i in S)) == demand[j], name='')
    for i in S:
        m.addConstr(gp.quicksum((x[i, j] for j in C)) <= supply[i], name='')
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print(f'ObjVal {m.ObjVal}')
        for i in S:
            for j in C:
                v = x[i, j]
                print(f'{v.VarName} {v.X}')
    else:
        print(f'Solver status: {m.Status}')
m = solve_walmart_transportation()